CREATE TABLE IF NOT EXISTS af_org(id BIGINT PRIMARY KEY,name VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS af_community(id BIGINT PRIMARY KEY,name VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS af_victim(id BIGINT PRIMARY KEY AUTO_INCREMENT,name_enc TEXT NOT NULL,phone_enc TEXT,identity_enc TEXT,community_id BIGINT,FOREIGN KEY(community_id) REFERENCES af_community(id));
CREATE TABLE IF NOT EXISTS af_user(id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(60) NOT NULL UNIQUE,password_hash VARCHAR(400) NOT NULL,display_name VARCHAR(80) NOT NULL,role VARCHAR(20) NOT NULL,org_id BIGINT,community_id BIGINT,victim_id BIGINT,enabled BOOLEAN NOT NULL DEFAULT TRUE,verified BOOLEAN NOT NULL DEFAULT FALSE,admin BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(org_id) REFERENCES af_org(id),FOREIGN KEY(community_id) REFERENCES af_community(id),FOREIGN KEY(victim_id) REFERENCES af_victim(id));
CREATE TABLE IF NOT EXISTS af_bank(id BIGINT PRIMARY KEY AUTO_INCREMENT,org_id BIGINT NOT NULL,number_hash CHAR(64) NOT NULL UNIQUE,number_enc TEXT NOT NULL,holder_enc TEXT NOT NULL,available DECIMAL(16,2) NOT NULL,FOREIGN KEY(org_id) REFERENCES af_org(id),CHECK(available>=0));
CREATE TABLE IF NOT EXISTS af_config(id BIGINT PRIMARY KEY AUTO_INCREMENT,data LONGTEXT NOT NULL,author_id BIGINT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS af_blacklist(id BIGINT PRIMARY KEY AUTO_INCREMENT,kind VARCHAR(20) NOT NULL,value_hash CHAR(64) NOT NULL,value_enc TEXT NOT NULL,source VARCHAR(200) NOT NULL,enabled BOOLEAN DEFAULT TRUE,INDEX ix_blacklist_value(kind,value_hash));
CREATE TABLE IF NOT EXISTS af_alert(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(40) NOT NULL UNIQUE,victim_id BIGINT,community_id BIGINT,state VARCHAR(30) NOT NULL DEFAULT '待研判',level VARCHAR(10) NOT NULL DEFAULT '低',score INT NOT NULL DEFAULT 0,needs_review BOOLEAN NOT NULL DEFAULT FALSE,reviewed_by BIGINT,review_note VARCHAR(1000),exception_note VARCHAR(1000),dispatch_error VARCHAR(300),root_time DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(victim_id) REFERENCES af_victim(id),FOREIGN KEY(community_id) REFERENCES af_community(id),INDEX(victim_id,root_time,state),INDEX(state,level,updated_at));
CREATE TABLE IF NOT EXISTS af_report(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(40) NOT NULL UNIQUE,request_key VARCHAR(80) NOT NULL UNIQUE,owner_id BIGINT,victim_id BIGINT,anonymous BOOLEAN NOT NULL,token_hash CHAR(64),kind VARCHAR(20) NOT NULL,value_hash CHAR(64) NOT NULL,value_enc TEXT NOT NULL,payload_enc LONGTEXT NOT NULL,source VARCHAR(20) NOT NULL,alert_id BIGINT,processing VARCHAR(30) NOT NULL DEFAULT '待研判',created_at DATETIME NOT NULL,FOREIGN KEY(owner_id) REFERENCES af_user(id),FOREIGN KEY(victim_id) REFERENCES af_victim(id),FOREIGN KEY(alert_id) REFERENCES af_alert(id),INDEX(owner_id,created_at),INDEX(alert_id));
CREATE TABLE IF NOT EXISTS af_score(id BIGINT PRIMARY KEY AUTO_INCREMENT,alert_id BIGINT NOT NULL,report_id BIGINT NOT NULL,config_id BIGINT NOT NULL,score INT NOT NULL,level VARCHAR(10) NOT NULL,details LONGTEXT NOT NULL,created_at DATETIME NOT NULL,FOREIGN KEY(alert_id) REFERENCES af_alert(id),FOREIGN KEY(report_id) REFERENCES af_report(id),FOREIGN KEY(config_id) REFERENCES af_config(id),INDEX(alert_id,id));
CREATE TABLE IF NOT EXISTS af_assessment(id BIGINT PRIMARY KEY AUTO_INCREMENT,alert_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,decision VARCHAR(30) NOT NULL,note VARCHAR(1000) NOT NULL,created_at DATETIME NOT NULL,FOREIGN KEY(alert_id) REFERENCES af_alert(id));
CREATE TABLE IF NOT EXISTS af_command(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(40) NOT NULL UNIQUE,kind VARCHAR(20) NOT NULL,alert_id BIGINT NOT NULL,original_id BIGINT,application_id BIGINT,bank_id BIGINT NOT NULL,org_id BIGINT NOT NULL,victim_id BIGINT NOT NULL,state VARCHAR(30) NOT NULL DEFAULT '已送达',requested DECIMAL(16,2),actual DECIMAL(16,2) NOT NULL DEFAULT 0,returned DECIMAL(16,2) NOT NULL DEFAULT 0,reserved DECIMAL(16,2) NOT NULL DEFAULT 0,remaining DECIMAL(16,2) NOT NULL DEFAULT 0,active_key VARCHAR(100) UNIQUE,extension_count INT NOT NULL DEFAULT 0,period_version INT NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,accepted_at DATETIME,expires_at DATETIME,FOREIGN KEY(alert_id) REFERENCES af_alert(id),FOREIGN KEY(original_id) REFERENCES af_command(id),FOREIGN KEY(bank_id) REFERENCES af_bank(id),FOREIGN KEY(org_id) REFERENCES af_org(id),FOREIGN KEY(victim_id) REFERENCES af_victim(id),INDEX(org_id,state,created_at),INDEX(state,expires_at),CHECK(actual>=0 AND returned>=0 AND reserved>=0 AND remaining>=0));
CREATE TABLE IF NOT EXISTS af_receipt(id BIGINT PRIMARY KEY AUTO_INCREMENT,command_id BIGINT NOT NULL,version INT NOT NULL,result VARCHAR(30) NOT NULL,amount DECIMAL(16,2) NOT NULL,reason VARCHAR(1000),voucher VARCHAR(100) NOT NULL,actor_id BIGINT NOT NULL,valid BOOLEAN DEFAULT TRUE,created_at DATETIME NOT NULL,UNIQUE(command_id,version),FOREIGN KEY(command_id) REFERENCES af_command(id));
CREATE TABLE IF NOT EXISTS af_ledger(id BIGINT PRIMARY KEY AUTO_INCREMENT,command_id BIGINT NOT NULL,action VARCHAR(40) NOT NULL,amount DECIMAL(16,2) NOT NULL,available_after DECIMAL(16,2) NOT NULL,note VARCHAR(500),created_at DATETIME NOT NULL,FOREIGN KEY(command_id) REFERENCES af_command(id));
CREATE TABLE IF NOT EXISTS af_visit(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(40) NOT NULL UNIQUE,alert_id BIGINT NOT NULL UNIQUE,community_id BIGINT NOT NULL,assignee_id BIGINT,state VARCHAR(30) NOT NULL DEFAULT '待接收',due_at DATETIME NOT NULL,arrived_at DATETIME,lat DECIMAL(10,6),lng DECIMAL(10,6),location_simulated BOOLEAN,process_text VARCHAR(2000),result VARCHAR(30),reason VARCHAR(1000),returned_at DATETIME,created_at DATETIME NOT NULL,FOREIGN KEY(alert_id) REFERENCES af_alert(id),FOREIGN KEY(community_id) REFERENCES af_community(id),FOREIGN KEY(assignee_id) REFERENCES af_user(id),INDEX(community_id,state,due_at));
CREATE TABLE IF NOT EXISTS af_application(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(40) NOT NULL UNIQUE,kind VARCHAR(20) NOT NULL,owner_id BIGINT NOT NULL,original_id BIGINT NOT NULL,state VARCHAR(30) NOT NULL,amount DECIMAL(16,2),approved DECIMAL(16,2),reason VARCHAR(2000) NOT NULL,payee_enc TEXT,note VARCHAR(2000),created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(owner_id) REFERENCES af_user(id),FOREIGN KEY(original_id) REFERENCES af_command(id),INDEX(owner_id,created_at));
CREATE TABLE IF NOT EXISTS af_campaign(id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(120) NOT NULL,community_id BIGINT NOT NULL,description VARCHAR(2000) NOT NULL,due_at DATETIME NOT NULL,state VARCHAR(30) NOT NULL DEFAULT '已发布',created_at DATETIME NOT NULL,FOREIGN KEY(community_id) REFERENCES af_community(id));
CREATE TABLE IF NOT EXISTS af_campaign_record(id BIGINT PRIMARY KEY AUTO_INCREMENT,campaign_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,form VARCHAR(80) NOT NULL,occurred_at DATETIME NOT NULL,sessions INT NOT NULL,people INT NOT NULL,note VARCHAR(1000),request_key VARCHAR(80) UNIQUE,created_at DATETIME NOT NULL,FOREIGN KEY(campaign_id) REFERENCES af_campaign(id),CHECK(sessions>0 AND people>=0));
CREATE TABLE IF NOT EXISTS af_article(id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(120) NOT NULL,category VARCHAR(30) NOT NULL,summary VARCHAR(300) NOT NULL,body TEXT NOT NULL,state VARCHAR(20) NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS af_attachment(id VARCHAR(40) PRIMARY KEY,owner_key VARCHAR(80) NOT NULL,user_id BIGINT,filename VARCHAR(180) NOT NULL,mime VARCHAR(80) NOT NULL,bytes BIGINT NOT NULL,entity_type VARCHAR(30),entity_id BIGINT,created_at DATETIME NOT NULL,INDEX(entity_type,entity_id));
CREATE TABLE IF NOT EXISTS af_notice(id BIGINT PRIMARY KEY AUTO_INCREMENT,command_id BIGINT NOT NULL,period_version INT NOT NULL,node VARCHAR(30) NOT NULL,message VARCHAR(300) NOT NULL,resolved BOOLEAN NOT NULL DEFAULT FALSE,resolution VARCHAR(1000),created_at DATETIME NOT NULL,UNIQUE(command_id,period_version,node),FOREIGN KEY(command_id) REFERENCES af_command(id));
CREATE TABLE IF NOT EXISTS af_correction(id BIGINT PRIMARY KEY AUTO_INCREMENT,command_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,state VARCHAR(20) NOT NULL DEFAULT '待审核',reason VARCHAR(1000) NOT NULL,new_result VARCHAR(30) NOT NULL,new_amount DECIMAL(16,2) NOT NULL,review_note VARCHAR(1000),created_at DATETIME NOT NULL,FOREIGN KEY(command_id) REFERENCES af_command(id));
CREATE TABLE IF NOT EXISTS af_log(id BIGINT PRIMARY KEY AUTO_INCREMENT,actor_id BIGINT,actor_role VARCHAR(20),action VARCHAR(80) NOT NULL,entity_type VARCHAR(30) NOT NULL,entity_id BIGINT,old_state VARCHAR(40),new_state VARCHAR(40),note VARCHAR(1000),created_at DATETIME NOT NULL,INDEX(entity_type,entity_id,id),INDEX(created_at));

CREATE TABLE IF NOT EXISTS af_migration(version INT PRIMARY KEY,applied_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS af_upload_guard(owner_key CHAR(64) PRIMARY KEY,touched_at DATETIME NOT NULL);

CREATE TABLE IF NOT EXISTS af_bank_origin(bank_id BIGINT PRIMARY KEY,opening DECIMAL(16,2) NOT NULL,source VARCHAR(30) NOT NULL,created_at DATETIME NOT NULL,FOREIGN KEY(bank_id) REFERENCES af_bank(id));
CREATE TABLE IF NOT EXISTS af_query_limit(client_key CHAR(64) PRIMARY KEY,attempts BIGINT NOT NULL,window_end DATETIME NOT NULL,INDEX(window_end));
CREATE TABLE IF NOT EXISTS af_audit_head(id INT PRIMARY KEY,last_id BIGINT NOT NULL,last_hash CHAR(64) NOT NULL,entry_count BIGINT NOT NULL,sealed_at DATETIME NOT NULL);

CREATE TABLE IF NOT EXISTS af_request_guard (
 request_key CHAR(64) PRIMARY KEY, touched_at DATETIME NOT NULL
);
CREATE TABLE IF NOT EXISTS af_rule_state (
 id INT PRIMARY KEY, blacklist_version BIGINT NOT NULL DEFAULT 0
);
INSERT IGNORE INTO af_rule_state(id,blacklist_version) VALUES(1,0);
